import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../core/repository.dart';

void refreshMargins(WidgetRef ref){ref.invalidate(marginContactProvider);ref.invalidate(marginWorkspacesProvider);ref.invalidate(marginWorkspaceProvider);ref.invalidate(marginPeersProvider);ref.invalidate(marginHistoryProvider);ref.invalidate(marginTransfersProvider);}
Future<bool> marginChange(BuildContext context,WidgetRef ref,void Function(RefractRepository) action)async{try{final repo=await ref.read(bootstrapProvider.future);if(!context.mounted){return false;}action(repo);refreshMargins(ref);return true;}catch(e){if(context.mounted){ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}return false;}}
Widget marginLoading()=>const Center(child:Padding(padding:EdgeInsets.all(24),child:CircularProgressIndicator()));
Widget marginError(Object e)=>Padding(padding:const EdgeInsets.all(16),child:SelectableText('$e'));
String marginTime(dynamic ts)=>ts is num?'${DateTime.fromMillisecondsSinceEpoch(ts.toInt()*1000,isUtc:true).toIso8601String().split('.').first} UTC':'Not recorded';
List<Map<String,dynamic>> marginRows(Map<String,dynamic> j,String key)=>((j[key] as List?)??[]).cast<Map<String,dynamic>>();
Future<bool> marginConfirm(BuildContext context,String title,String detail)async=>await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:Text(title),content:Text(detail),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('Confirm'))]))??false;
Future<void> marginCode(BuildContext context,String title,String code)async{await showDialog<void>(context:context,builder:(ctx)=>AlertDialog(title:Text(title),content:SizedBox(width:500,height:320,child:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Copying is explicit. Encrypted transfers still expose routing metadata. Use a channel appropriate for your collaborators. Never copy a private database or device secret.'),const SizedBox(height:12),if(code.length>4000)Text('Display abbreviated (${code.length} characters). Copy includes the complete package.'),SelectableText(code.length>4000?code.substring(0,4000):code)]))),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Close')),FilledButton.icon(onPressed:()async{await Clipboard.setData(ClipboardData(text:code));if(ctx.mounted){ScaffoldMessenger.of(ctx).showSnackBar(const SnackBar(content:Text('Copied. No delivery or synchronization is implied.')));}},icon:const Icon(Icons.copy),label:const Text('Copy complete package'))]));}
Future<String?> marginPrompt(BuildContext context,String title,{String initial=''})async=>showDialog<String>(context:context,builder:(_)=>_Prompt(title:title,initial:initial));
class _Prompt extends StatefulWidget{const _Prompt({required this.title,required this.initial});final String title,initial;@override State<_Prompt> createState()=>_PromptState();}
class _PromptState extends State<_Prompt>{late final _text=TextEditingController(text:widget.initial);@override void dispose(){_text.dispose();super.dispose();}@override Widget build(BuildContext context)=>AlertDialog(title:Text(widget.title),content:TextField(controller:_text,maxLength:120,autofocus:true),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(context,_text.text),child:const Text('Save locally'))]);}
